<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/capacity_guard.php';
require_login(); require_clothing_warehouse_access();

$movementOptions = [
    'Inbound - Purchase Receive' => 'Inbound — Purchase Receive',
    'Inbound - Customer Return' => 'Inbound — Customer Return',
    'Inbound - Production In' => 'Inbound — Production / Processing In',
    'Outbound - Retail Store Delivery' => 'Outbound — Retail Store Delivery',
    'Outbound - Customer Order Picking' => 'Outbound — Customer Order Picking',
    'Outbound - Damage or Scrap' => 'Outbound — Damage / Scrap Write-off',
    'Outbound - Return to Supplier' => 'Outbound — Return to Supplier',
    'Transfer - Internal Location Change' => 'Transfer — Internal Location Change',
];
function movement_direction(string $type): string { return str_starts_with($type, 'Inbound') ? 'inbound' : (str_starts_with($type, 'Transfer') ? 'transfer' : 'outbound'); }

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $productId = (int) ($_POST['product_id'] ?? 0); $type = $_POST['movement_type'] ?? ''; $quantity = (int) ($_POST['quantity'] ?? 0);
    if ($quantity <= 0 || !array_key_exists($type, $movementOptions)) exit('Choose a valid stock movement type and quantity.');
    $direction = movement_direction($type); $pdo->beginTransaction();
    try {
        $productQuery = $pdo->prepare('SELECT product_code, product_name, current_quantity, unit_cost, selling_price, location_id FROM products WHERE id = ? FOR UPDATE');
        $productQuery->execute([$productId]); $product = $productQuery->fetch(PDO::FETCH_ASSOC);
        if (!$product) throw new RuntimeException('Clothing item not found.');
        $sourceLocationId = (int) ($_POST['source_location_id'] ?? 0); $destinationLocationId = (int) ($_POST['destination_location_id'] ?? 0);
        $locationId = (int) ($_POST['location_id'] ?? 0) ?: null; $available = (int) $product['current_quantity']; $change = $direction === 'inbound' ? $quantity : -$quantity;
        if ($direction === 'transfer') {
            if (!$sourceLocationId || !$destinationLocationId || $sourceLocationId === $destinationLocationId) throw new RuntimeException('Choose different source and destination locations.');
            if ($quantity !== $available) throw new RuntimeException('This system stores one primary location per SKU. For a transfer, move the full available quantity shown on screen.');
            guard_location_capacity($pdo, $destinationLocationId, $available);
            $locationId = $destinationLocationId; $change = 0;
        } elseif ($direction === 'inbound') {
            guard_location_capacity($pdo, (int) $locationId, $quantity);
        } elseif ($available + $change < 0) throw new RuntimeException('Insufficient stock for this outbound movement.');
        $locationCode = function (int $id) use ($pdo): string { $lookup = $pdo->prepare('SELECT location_code FROM warehouse_locations WHERE id = ?'); $lookup->execute([$id]); return (string) ($lookup->fetchColumn() ?: 'Unknown'); };
        $notes = trim($_POST['notes'] ?? '') ?: null; $partnerCompany = trim($_POST['partner_company'] ?? '') ?: null; $partnerAddress = trim($_POST['partner_address'] ?? '') ?: null;
        if ($direction === 'transfer') { $from = $locationCode($sourceLocationId); $to = $locationCode($destinationLocationId); $partnerCompany = 'Internal warehouse transfer'; $partnerAddress = $from . ' → ' . $to; $notes = trim('Transferred from ' . $from . ' to ' . $to . '. ' . ($notes ?? '')); }
        $prefix = $direction === 'inbound' ? 'IN' : ($direction === 'transfer' ? 'TRF' : 'OUT');
        $code = $prefix . '-' . date('Ymd') . '-' . random_int(100, 999);
        $pdo->prepare('INSERT INTO stock_movements(movement_code,product_id,location_id,movement_type,quantity,unit_cost,selling_price,reference_no,partner_company,partner_address,notes,created_by,partner_contact) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$code, $productId, $locationId, $type, $quantity, $product['unit_cost'], $product['selling_price'], trim($_POST['reference_no'] ?? '') ?: null, $partnerCompany, $partnerAddress, $notes, $_SESSION['user']['id'], $direction === 'transfer' ? null : (trim($_POST['partner_contact'] ?? '') ?: null)]);
        if ($direction === 'transfer') $pdo->prepare('UPDATE products SET location_id = ? WHERE id = ?')->execute([$destinationLocationId, $productId]); else $pdo->prepare('UPDATE products SET current_quantity = current_quantity + ? WHERE id = ?')->execute([$change, $productId]);
        $pdo->commit();
        if ($direction === 'transfer') {
            $_SESSION['movement_success'] = 'Success — ' . $code . ' saved. ' . $product['product_code'] . ' (' . $product['product_name'] . ') was transferred to the new storage location.';
        } else {
            $newStock = $available + $change;
            $_SESSION['movement_success'] = 'Success — ' . $code . ' saved: ' . $quantity . ' pcs of ' . $product['product_code'] . ' (' . $product['product_name'] . '). Available stock is now ' . $newStock . ' pcs.';
        }
    } catch (Throwable $exception) { if ($pdo->inTransaction()) $pdo->rollBack(); flash($exception->getMessage()); }
    header('Location: movements.php'); exit;
}
$products = $pdo->query("SELECT id, product_code, barcode, product_name, current_quantity, unit, location_id, company_name, company_contact, brand, colour, size_label FROM products WHERE status = 'Active' ORDER BY product_name")->fetchAll(PDO::FETCH_ASSOC);
$locations = $pdo->query("SELECT l.id, l.location_code, l.capacity, COALESCE(SUM(p.current_quantity), 0) AS current_stock FROM warehouse_locations l LEFT JOIN products p ON p.location_id = l.id AND p.status = 'Active' WHERE l.status = 'Active' GROUP BY l.id ORDER BY l.location_code")->fetchAll(PDO::FETCH_ASSOC);
$rows = $pdo->query('SELECT m.*, p.product_name, p.product_code, p.colour, p.size_label, u.name FROM stock_movements m JOIN products p ON p.id = m.product_id JOIN users u ON u.id = m.created_by ORDER BY m.created_at DESC LIMIT 30')->fetchAll(PDO::FETCH_ASSOC);
$page_title = 'Stock Movement'; require __DIR__ . '/../includes/header.php';
$movementSuccess = $_SESSION['movement_success'] ?? '';
unset($_SESSION['movement_success']);
?>
<?php if ($movementSuccess): ?><div class="alert alert-success alert-dismissible fade show d-flex align-items-center gap-2" role="alert"><i class="bi bi-check-circle-fill fs-4"></i><div><b>Stock movement saved successfully.</b><br><span><?= e($movementSuccess) ?></span></div><button class="btn-close ms-auto" data-bs-dismiss="alert"></button></div><?php endif; ?>
<div class="mb-4"><h1 class="page-heading">Stock Movement</h1><p class="page-subtitle mb-0">Receive clothing, dispatch it, record write-offs, or move a complete SKU variant to another storage location.</p></div>
<form method="post" id="stockMovementForm"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><div class="alert alert-danger d-none" id="movementRequiredError" role="alert"><b>Please complete the required fields:</b><span id="movementRequiredList"></span></div>
<div class="panel mb-4"><div class="d-flex align-items-center gap-2 mb-3"><span class="badge text-bg-primary">1</span><h2 class="h6 mb-0">Movement Details</h2><span class="text-muted small">Quickly find a SKU, choose its operation, then enter the quantity.</span></div><div class="row g-3">
<div class="col-md-6"><label class="form-label">Clothing Item / SKU *</label><div class="input-group"><select name="product_id" id="productSelect" class="form-select" required><option value="">— Select clothing item / SKU —</option><?php foreach ($products as $product): ?><option value="<?= $product['id'] ?>" data-sku="<?= e($product['product_code']) ?>" data-barcode="<?= e($product['barcode'] ?? '') ?>" data-company="<?= e($product['company_name'] ?? '') ?>" data-contact="<?= e($product['company_contact'] ?? '') ?>" data-colour="<?= e($product['colour'] ?? '') ?>" data-size="<?= e($product['size_label'] ?? '') ?>" data-brand="<?= e($product['brand'] ?? '') ?>" data-stock="<?= number_format((float) $product['current_quantity'], 0, '.', '') ?>" data-unit="<?= e($product['unit']) ?>" data-location="<?= (int) $product['location_id'] ?>"><?= e($product['product_code'] . ' — ' . $product['product_name'] . ' · ' . ($product['colour'] ?: 'No colour') . ' · Size ' . ($product['size_label'] ?: '—')) ?></option><?php endforeach ?></select><button class="btn btn-outline-primary" type="button" id="toggleScanButton"><i class="bi bi-upc-scan"></i> Scan Barcode</button></div><div class="mt-2 d-none" id="scannerPanel"><div class="input-group"><input id="quickScan" class="form-control" autocomplete="off" placeholder="Type SKU, barcode, or item name to search"><button class="btn btn-outline-primary" type="button" id="findSkuButton">Find</button></div><div id="scanResults" class="list-group mt-1 d-none"></div><div class="d-flex align-items-center gap-2 mt-2"><button class="btn btn-sm btn-outline-success" type="button" id="cameraScanButton"><i class="bi bi-camera"></i> Use Camera</button><span class="form-text m-0" id="scanMessage">Type to see matching clothing items, scan with a scanner keyboard, or choose Use Camera.</span></div><div class="border rounded p-2 mt-2 d-none" id="cameraPanel"><video id="cameraVideo" class="w-100 rounded bg-dark" style="max-height:260px;object-fit:cover" playsinline muted></video><div class="d-flex justify-content-between align-items-center mt-2"><small id="cameraStatus" class="text-muted">Point the camera at the barcode.</small><button class="btn btn-sm btn-outline-danger" type="button" id="stopCameraButton">Stop Camera</button></div></div></div></div>
<div class="col-md-3"><label class="form-label">Movement Type *</label><select name="movement_type" id="movementType" class="form-select"><?php foreach ($movementOptions as $value => $label): ?><option value="<?= e($value) ?>"><?= e($label) ?></option><?php endforeach ?></select></div>
<div class="col-md-3"><label class="form-label">Quantity (pcs) *</label><input type="number" min="1" step="1" name="quantity" id="movementQuantity" class="form-control" placeholder="0" required></div>
<div class="col-md-3 non-transfer"><label class="form-label">Storage Location</label><select name="location_id" id="locationSelect" class="form-select"><option value="">— Select —</option><?php foreach ($locations as $location): ?><option value="<?= $location['id'] ?>" data-capacity="<?= (int) $location['capacity'] ?>" data-current-stock="<?= (int) $location['current_stock'] ?>"><?= e($location['location_code']) ?></option><?php endforeach ?></select></div>
<div class="col-md-3 transfer-only d-none"><label class="form-label">Source Location *</label><select name="source_location_id" id="sourceLocationSelect" class="form-select"><option value="">— Select source —</option><?php foreach ($locations as $location): ?><option value="<?= $location['id'] ?>"><?= e($location['location_code']) ?></option><?php endforeach ?></select></div><div class="col-md-3 transfer-only d-none"><label class="form-label">Destination Location *</label><select name="destination_location_id" id="destinationLocationSelect" class="form-select"><option value="">— Select destination —</option><?php foreach ($locations as $location): ?><option value="<?= $location['id'] ?>" data-capacity="<?= (int) $location['capacity'] ?>" data-current-stock="<?= (int) $location['current_stock'] ?>"><?= e($location['location_code']) ?></option><?php endforeach ?></select></div>
<div class="col-12"><div class="alert alert-light border mb-0 py-2"><i class="bi bi-tags"></i> Selected Variant: <b id="variantBrand">—</b> · Colour: <b id="variantColour">—</b> · Size: <b id="variantSize">—</b><span class="ms-3">Available Stock: <b id="availableStock">—</b></span><span class="ms-3">After Movement: <b id="afterStock">—</b></span><span class="text-muted ms-2 small" id="stockHint">Enter a quantity to preview stock.</span></div></div></div></div>
<div class="alert alert-danger d-none mt-3 mb-0" id="capacityWarning" role="alert"></div>
<div class="panel mb-4" id="partnerPanel"><div class="d-flex align-items-center gap-2 mb-3"><span class="badge text-bg-primary">2</span><h2 class="h6 mb-0">Business Partner</h2><span class="text-muted small" id="partnerHelp">Supplier for inbound; customer or retail store for outbound.</span></div><div class="row g-3"><div class="col-md-6"><label class="form-label" id="companyLabel">Received From — Supplier *</label><input name="partner_company" id="partnerCompany" class="form-control" placeholder="Supplier company name" required><label class="form-label mt-2" for="partnerContact">Contact</label><input name="partner_contact" id="partnerContact" class="form-control" maxlength="160" placeholder="Phone number or email"></div><div class="col-md-6"><label class="form-label" id="addressLabel">Receiving Address *</label><input name="partner_address" id="partnerAddress" class="form-control" placeholder="Full business address" required></div></div></div>
<div class="panel mb-4" id="referencePanel"><div class="d-flex align-items-center gap-2 mb-3"><span class="badge text-bg-primary">3</span><h2 class="h6 mb-0">Reference and Notes</h2><span class="text-muted small">Reference is required; Clothing Notes are optional.</span></div><div class="row g-3"><div class="col-md-4"><label class="form-label" id="referenceLabel">Goods Received Note / Purchase Order No. *</label><input name="reference_no" class="form-control" id="referenceNo" placeholder="e.g. GRN-2026-001"></div><div class="col-md-8"><label class="form-label">Clothing Notes</label><input name="notes" class="form-control" placeholder="e.g. carton number, seasonal collection, reason for write-off"></div></div></div>
<div class="d-flex justify-content-end"><button class="btn btn-primary px-4"><i class="bi bi-check2-circle"></i> Save Stock Movement</button></div></form>
<div class="panel table-responsive"><h2 class="h6 mb-3">Recent Stock Movements</h2><table class="table"><thead><tr><th>Date</th><th>Clothing Item</th><th>Colour / Size</th><th>Movement Type</th><th>Quantity</th><th>Partner / Transfer</th><th>Address / Location</th><th>Reference No.</th></tr></thead><tbody><?php foreach ($rows as $row): $badge = str_starts_with($row['movement_type'], 'Inbound') ? 'success' : (str_starts_with($row['movement_type'], 'Transfer') ? 'warning' : 'primary'); ?><tr><td><?= e($row['created_at']) ?></td><td><?= e($row['product_code'] . ' — ' . $row['product_name']) ?></td><td><?= e(($row['colour'] ?? '—') . ' / ' . ($row['size_label'] ?? '—')) ?></td><td><span class="badge text-bg-<?= $badge ?>"><?= e($row['movement_type']) ?></span></td><td><?= number_format((float) $row['quantity'], 0) ?></td><td><?= e($row['partner_company'] ?? '—') ?><?php if (!empty($row['partner_contact'])): ?><br><small class="text-muted"><?= e($row['partner_contact']) ?></small><?php endif; ?></td><td><?= e($row['partner_address'] ?? '—') ?></td><td><?= e($row['reference_no'] ?? '—') ?></td></tr><?php endforeach; if (!$rows): ?><tr><td colspan="8" class="empty">No stock movements recorded yet.</td></tr><?php endif ?></tbody></table></div>
<script>
const movementType = document.getElementById('movementType'), productSelect = document.getElementById('productSelect'), quantityInput = document.getElementById('movementQuantity'), locationSelect = document.getElementById('locationSelect'), sourceLocationSelect = document.getElementById('sourceLocationSelect'), destinationLocationSelect = document.getElementById('destinationLocationSelect'), partnerCompany = document.getElementById('partnerCompany'), partnerAddress = document.getElementById('partnerAddress');
const labels = { inbound: { company: 'Received From — Supplier *', address: 'Receiving Address *', reference: 'Goods Received Note / Purchase Order No. *', help: 'Record stock received from a supplier.', placeholder: 'Supplier company name' }, outbound: { company: 'Delivered To — Customer / Retail Store *', address: 'Delivery Address *', reference: 'Delivery Order / Invoice / Pick List No. *', help: 'Record goods sent to a customer, retail store, supplier, or write-off destination.', placeholder: 'Customer, store, or supplier name' } };
function direction() { return movementType.value.startsWith('Inbound') ? 'inbound' : (movementType.value.startsWith('Transfer') ? 'transfer' : 'outbound'); }
function selectedProduct() { const option = productSelect.options[productSelect.selectedIndex]; return option && option.value ? option : null; }
function updateQuantityLimit() { const item = selectedProduct(), mode = direction(); if (!item) { quantityInput.removeAttribute('max'); quantityInput.readOnly = false; quantityInput.title = ''; return; } const available = Number(item.dataset.stock || 0); if (mode === 'inbound') { quantityInput.removeAttribute('max'); quantityInput.readOnly = false; quantityInput.title = ''; } else if (mode === 'transfer') { quantityInput.value = available || ''; quantityInput.max = available; quantityInput.readOnly = true; quantityInput.title = 'A transfer moves the full SKU quantity to its new primary location.'; } else { quantityInput.max = available; quantityInput.readOnly = false; quantityInput.title = 'Available stock: ' + available + ' ' + (item.dataset.unit || 'pcs'); } }
function checkCapacityPreview() { const warning = document.getElementById('capacityWarning'), mode = direction(), destination = mode === 'transfer' ? destinationLocationSelect : locationSelect, option = destination.options[destination.selectedIndex], qty = mode === 'transfer' ? Number(quantityInput.value || selectedProduct()?.dataset.stock || 0) : Number(quantityInput.value || 0); warning.classList.add('d-none'); warning.textContent = ''; if (mode === 'outbound' || !option?.value || qty <= 0) return true; const capacity = Number(option.dataset.capacity || 0), current = Number(option.dataset.currentStock || 0), projected = current + qty; if (projected >= capacity * 0.9) { warning.textContent = `Storage location ${option.textContent.trim()} is full or nearly full (${current} / ${capacity} pcs). Adding ${qty} pcs would bring it to ${projected} pcs. The 90% limit prevents this stock addition.`; warning.classList.remove('d-none'); return false; } return true; }
function updateStockPreview() { const item = selectedProduct(); if (!item) { document.getElementById('availableStock').textContent = '—'; document.getElementById('afterStock').textContent = '—'; document.getElementById('afterStock').className = ''; document.getElementById('stockHint').textContent = 'Select a clothing item to preview stock.'; checkCapacityPreview(); return; } const available = Number(item.dataset.stock || 0), qty = Number(quantityInput.value || 0), mode = direction(), unit = item.dataset.unit || 'pcs'; const after = mode === 'inbound' ? available + qty : (mode === 'transfer' ? available : available - qty); document.getElementById('availableStock').textContent = available + ' ' + unit; document.getElementById('afterStock').textContent = after + ' ' + unit; document.getElementById('afterStock').className = after < 0 ? 'text-danger' : (mode === 'inbound' ? 'text-success' : ''); document.getElementById('stockHint').textContent = mode === 'transfer' ? 'Transfer keeps quantity unchanged and updates the SKU primary location.' : (after < 0 ? 'Quantity is higher than available stock.' : 'Preview only; it will be saved after confirmation.'); checkCapacityPreview(); }
function syncPartnerContact() { document.getElementById('partnerContact').value = direction() === 'inbound' && movementType.value !== 'Inbound - Customer Return' ? (selectedProduct()?.dataset.contact || '') : ''; }
function updateLabels() { syncPartnerContact(); const mode = direction(), isTransfer = mode === 'transfer', isCustomerReturn = movementType.value === 'Inbound - Customer Return'; document.querySelectorAll('.transfer-only').forEach(el => el.classList.toggle('d-none', !isTransfer)); document.querySelectorAll('.non-transfer').forEach(el => el.classList.toggle('d-none', isTransfer)); document.getElementById('partnerPanel').classList.toggle('d-none', isTransfer); document.getElementById('referencePanel').classList.toggle('d-none', isTransfer); partnerCompany.required = !isTransfer; partnerAddress.required = !isTransfer; sourceLocationSelect.required = isTransfer; destinationLocationSelect.required = isTransfer; if (!isTransfer) { const info = isCustomerReturn ? { company: 'Returned By — Customer *', address: 'Customer Return Address *', reference: 'Customer Return / RMA No. *', help: 'Record clothing returned by a customer. Enter the customer details instead of the supplier.', placeholder: 'Customer name or company' } : labels[mode]; document.getElementById('companyLabel').textContent = info.company; document.getElementById('addressLabel').textContent = info.address; document.getElementById('referenceLabel').textContent = info.reference; document.getElementById('partnerHelp').textContent = info.help; partnerCompany.placeholder = info.placeholder; if (mode === 'inbound') { const item = selectedProduct(); partnerCompany.value = isCustomerReturn ? '' : (item?.dataset.company || ''); } } updateQuantityLimit(); updateStockPreview(); }
function updateVariant() { syncPartnerContact(); const item = selectedProduct(); if (!item) { document.getElementById('variantBrand').textContent = '—'; document.getElementById('variantColour').textContent = '—'; document.getElementById('variantSize').textContent = '—'; locationSelect.value = ''; sourceLocationSelect.value = ''; updateQuantityLimit(); updateStockPreview(); return; } document.getElementById('variantBrand').textContent = item.dataset.brand || '—'; document.getElementById('variantColour').textContent = item.dataset.colour || '—'; document.getElementById('variantSize').textContent = item.dataset.size || '—'; locationSelect.value = item.dataset.location || ''; sourceLocationSelect.value = item.dataset.location || ''; if (direction() === 'inbound') partnerCompany.value = movementType.value === 'Inbound - Customer Return' ? '' : (item.dataset.company || ''); updateQuantityLimit(); updateStockPreview(); }
const quickScan = document.getElementById('quickScan'), scanResults = document.getElementById('scanResults'), scanMessage = document.getElementById('scanMessage');
function matchingProducts(query) { const text = query.trim().toLowerCase(); if (!text) return []; return Array.from(productSelect.options).filter(option => option.value && ((option.dataset.sku || '').toLowerCase().includes(text) || (option.dataset.barcode || '').toLowerCase().includes(text) || option.textContent.toLowerCase().includes(text))); }
function chooseProduct(option) { productSelect.value = option.value; quickScan.value = option.dataset.sku; scanResults.innerHTML = ''; scanResults.classList.add('d-none'); updateVariant(); scanMessage.textContent = 'Selected: ' + option.dataset.sku; scanMessage.className = 'form-text text-success'; }
function showMatches() { const matches = matchingProducts(quickScan.value); scanResults.innerHTML = ''; if (!quickScan.value.trim()) { scanResults.classList.add('d-none'); return; } if (!matches.length) { scanResults.classList.add('d-none'); scanMessage.textContent = 'No active clothing item matches this SKU, barcode, or item name.'; scanMessage.className = 'form-text text-danger'; return; } scanMessage.textContent = matches.length + ' matching item(s). Choose one below.'; scanMessage.className = 'form-text text-muted'; matches.slice(0, 8).forEach(option => { const result = document.createElement('button'); result.type = 'button'; result.className = 'list-group-item list-group-item-action py-2'; result.textContent = option.dataset.sku + (option.dataset.barcode ? ' · Barcode: ' + option.dataset.barcode : '') + ' — ' + option.textContent.split(' — ').slice(1).join(' — '); result.addEventListener('click', () => chooseProduct(option)); scanResults.appendChild(result); }); scanResults.classList.remove('d-none'); }
function findSku() { const matches = matchingProducts(quickScan.value); const query = quickScan.value.trim().toLowerCase(); const exact = matches.find(option => option.dataset.sku.toLowerCase() === query || (option.dataset.barcode || '').toLowerCase() === query); if (exact) chooseProduct(exact); else showMatches(); }
let cameraStream = null, cameraFrame = null, barcodeDetector = null;
const cameraPanel = document.getElementById('cameraPanel'), cameraVideo = document.getElementById('cameraVideo'), cameraStatus = document.getElementById('cameraStatus');
function stopCameraScan() { if (cameraFrame) cancelAnimationFrame(cameraFrame); cameraFrame = null; if (cameraStream) cameraStream.getTracks().forEach(track => track.stop()); cameraStream = null; cameraVideo.srcObject = null; cameraPanel.classList.add('d-none'); }
async function detectFromCamera() { if (!cameraStream || !barcodeDetector) return; try { const codes = await barcodeDetector.detect(cameraVideo); if (codes.length) { document.getElementById('quickScan').value = codes[0].rawValue; findSku(); cameraStatus.textContent = 'Barcode found: ' + codes[0].rawValue; stopCameraScan(); return; } } catch (error) { cameraStatus.textContent = 'Keep the barcode inside the camera frame.'; } cameraFrame = requestAnimationFrame(detectFromCamera); }
async function startCameraScan() { if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) { cameraStatus.textContent = 'Camera access is not supported by this browser.'; cameraPanel.classList.remove('d-none'); return; } try { cameraStatus.textContent = 'Requesting camera permission…'; cameraPanel.classList.remove('d-none'); cameraStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: { ideal: 'environment' } }, audio: false }); cameraVideo.srcObject = cameraStream; await cameraVideo.play(); if (!('BarcodeDetector' in window)) { cameraStatus.textContent = 'Camera is on, but this browser cannot automatically read barcodes. Use the newest Chrome or enter the code manually.'; return; } const preferredFormats = ['ean_13', 'ean_8', 'code_128', 'code_39', 'upc_a', 'upc_e', 'qr_code']; const supportedFormats = await BarcodeDetector.getSupportedFormats(); const formats = preferredFormats.filter(format => supportedFormats.includes(format)); if (!formats.length) { cameraStatus.textContent = 'Camera is on, but no supported barcode format was found in this browser.'; return; } barcodeDetector = new BarcodeDetector({ formats }); cameraStatus.textContent = 'Camera is on. Point the barcode clearly at the camera.'; detectFromCamera(); } catch (error) { const detail = error && error.name === 'NotAllowedError' ? 'Camera permission was denied. Click the camera icon beside the address bar and allow this site.' : 'Unable to start the camera: ' + (error && error.message ? error.message : 'no camera is available.'); cameraStatus.textContent = detail; cameraPanel.classList.remove('d-none'); } }
const stockMovementForm = document.getElementById('stockMovementForm'), movementRequiredError = document.getElementById('movementRequiredError'), movementRequiredList = document.getElementById('movementRequiredList');
function movementFieldsToCheck() { return direction() === 'transfer' ? [['product_id', 'Clothing Item / SKU'], ['movement_type', 'Movement Type'], ['quantity', 'Quantity'], ['source_location_id', 'Source Location'], ['destination_location_id', 'Destination Location']] : [['product_id', 'Clothing Item / SKU'], ['movement_type', 'Movement Type'], ['quantity', 'Quantity'], ['location_id', 'Storage Location'], ['partner_company', 'Business Partner'], ['partner_address', 'Business Address'], ['reference_no', 'Reference Number']]; }
function validateMovementFields() { const fields = movementFieldsToCheck(); const missing = fields.filter(([name]) => !String(stockMovementForm.elements[name]?.value || '').trim()); if (Number(quantityInput.value || 0) <= 0 && !missing.some(([name]) => name === 'quantity')) missing.push(['quantity', 'Quantity (must be more than 0)']); document.querySelectorAll('#stockMovementForm .is-invalid').forEach(element => element.classList.remove('is-invalid')); if (!missing.length) { movementRequiredError.classList.add('d-none'); return true; } missing.forEach(([name]) => stockMovementForm.elements[name]?.classList.add('is-invalid')); movementRequiredList.textContent = ' ' + missing.map(([, label]) => label).join(', ') + '.'; movementRequiredError.classList.remove('d-none'); missing[0] && stockMovementForm.elements[missing[0][0]].focus(); movementRequiredError.scrollIntoView({ behavior: 'smooth', block: 'center' }); return false; }
stockMovementForm.noValidate = true; stockMovementForm.addEventListener('submit', event => { if (!validateMovementFields() || !checkCapacityPreview()) { event.preventDefault(); document.getElementById('capacityWarning').scrollIntoView({ behavior: 'smooth', block: 'center' }); } });
document.getElementById('findSkuButton').addEventListener('click', findSku); quickScan.addEventListener('input', showMatches); quickScan.addEventListener('keydown', event => { if (event.key === 'Enter') { event.preventDefault(); findSku(); } }); document.getElementById('toggleScanButton').addEventListener('click', () => { const panel = document.getElementById('scannerPanel'); panel.classList.toggle('d-none'); if (!panel.classList.contains('d-none')) quickScan.focus(); }); document.getElementById('cameraScanButton').addEventListener('click', startCameraScan); document.getElementById('stopCameraButton').addEventListener('click', stopCameraScan); window.addEventListener('beforeunload', stopCameraScan); movementType.addEventListener('change', updateLabels); productSelect.addEventListener('change', updateVariant); quantityInput.addEventListener('input', updateStockPreview); locationSelect.addEventListener('change', updateStockPreview); destinationLocationSelect.addEventListener('change', updateStockPreview); updateLabels(); updateVariant();
</script>
